1	import { memo, useCallback, useEffect, useMemo, useRef, useState } from "react";
2	import { useLocation } from "react-router-dom";
3	import { useAuth } from "@/contexts/AuthContext";
4	import useCurrentUser from "@/hooks/useCurrentUser";
5	import { useUser } from "@/hooks/useUserQueries";
6	import { findTagMetadata } from "@/lib/tag";
7	import { cn } from "@/lib/utils";
8	import { State } from "@/types/proto/api/v1/common_pb";
9	import { isSuperUser } from "@/utils/user";
10	import MemoShareImageDialog from "../MemoActionMenu/MemoShareImageDialog";
11	import MemoEditor from "../MemoEditor";
12	import PreviewImageDialog from "../PreviewImageDialog";
13	import { MemoBody, MemoCommentListView, MemoHeader } from "./components";
14	import { MEMO_CARD_BASE_CLASSES } from "./constants";
15	import { useImagePreview } from "./hooks";
16	import { computeCommentAmount, MemoViewContext } from "./MemoViewContext";
17	import type { MemoViewProps } from "./types";
18	
19	const MemoView: React.FC<MemoViewProps> = (props: MemoViewProps) => {
20	  const { memo: memoData, className, parentPage: parentPageProp, compact, showCreator, showVisibility, showPinned } = props;
21	  const cardRef = useRef<HTMLDivElement>(null);
22	  const [showEditor, setShowEditor] = useState(false);
23	  const [cardWidth, setCardWidth] = useState(0);
24	
25	  const currentUser = useCurrentUser();
26	  const { userTagsSetting } = useAuth();
27	  const creator = useUser(memoData.creator).data;
28	  const isArchived = memoData.state === State.ARCHIVED;
29	  const readonly = memoData.creator !== currentUser?.name && !isSuperUser(currentUser);
30	  const parentPage = parentPageProp || "/";
31	
32	  // Blur content when any tag has blur_content enabled in the current user's tag settings.
33	  const [showBlurredContent, setShowBlurredContent] = useState(false);
34	  const blurred = memoData.tags?.some((tag) => userTagsSetting && findTagMetadata(tag, userTagsSetting)?.blurContent) ?? false;
35	  const toggleBlurVisibility = useCallback(() => setShowBlurredContent((prev) => !prev), []);
36	
37	  const { previewState, openPreview, setPreviewOpen } = useImagePreview();
38	
39	  const openEditor = useCallback(() => setShowEditor(true), []);
40	  const closeEditor = useCallback(() => setShowEditor(false), []);
41	
42	  const location = useLocation();
43	  const isInMemoDetailPage = location.pathname.startsWith(`/${memoData.name}`) || location.pathname.startsWith("/memos/shares/");
44	  const showCommentPreview = !isInMemoDetailPage && computeCommentAmount(memoData) > 0;
45	
46	  useEffect(() => {
47	    const card = cardRef.current;
48	    if (!card) {
49	      return;
50	    }
51	
52	    const updateWidth = (nextWidth?: number) => {
53	      const width = Math.round(nextWidth ?? card.getBoundingClientRect().width);
54	      setCardWidth((prev) => (prev === width ? prev : width));
55	    };
56	
57	    updateWidth();
58	
59	    if (typeof ResizeObserver === "undefined") {
60	      const handleResize = () => updateWidth();
61	      window.addEventListener("resize", handleResize);
62	      return () => window.removeEventListener("resize", handleResize);
63	    }
64	
65	    const resizeObserver = new ResizeObserver((entries) => {
66	      updateWidth(entries[0]?.contentRect.width);
67	    });
68	
69	    resizeObserver.observe(card);
70	    return () => resizeObserver.disconnect();
71	  }, []);
72	
73	  const contextValue = useMemo(
74	    () => ({
75	      memo: memoData,
76	      creator,
77	      currentUser,
78	      parentPage,
79	      cardWidth,
80	      isArchived,
81	      readonly,
82	      showBlurredContent,
83	      blurred,
84	      openEditor,
85	      toggleBlurVisibility,
86	      openPreview,
87	    }),
88	    [
89	      memoData,
90	      creator,
91	      currentUser,
92	      parentPage,
93	      cardWidth,
94	      isArchived,
95	      readonly,
96	      showBlurredContent,
97	      blurred,
98	      openEditor,
99	      toggleBlurVisibility,
100	      openPreview,
101	    ],
102	  );
103	
104	  if (showEditor) {
105	    return (
106	      <MemoEditor
107	        autoFocus
108	        className="mb-2"
109	        cacheKey={`inline-memo-editor-${memoData.name}`}
110	        memo={memoData}
111	        parentMemoName={memoData.parent || undefined}
112	        onConfirm={closeEditor}
113	        onCancel={closeEditor}
114	      />
115	    );
116	  }
117	
118	  const article = (
119	    <article
120	      className={cn(MEMO_CARD_BASE_CLASSES, showCommentPreview ? "mb-0 rounded-b-none" : "mb-2", className)}
121	      ref={cardRef}
122	      tabIndex={readonly ? -1 : 0}
123	    >
124	      <MemoHeader showCreator={showCreator} showVisibility={showVisibility} showPinned={showPinned} />
125	
126	      <MemoBody compact={compact} />
127	
128	      <PreviewImageDialog
129	        open={previewState.open}
130	        onOpenChange={setPreviewOpen}
131	        items={previewState.items}
132	        initialIndex={previewState.index}
133	      />
134	
135	      {props.onShareImageDialogOpenChange && (
136	        <MemoShareImageDialog open={Boolean(props.shareImageDialogOpen)} onOpenChange={props.onShareImageDialogOpenChange} />
137	      )}
138	    </article>
139	  );
140	
141	  return (
142	    <MemoViewContext.Provider value={contextValue}>
143	      {showCommentPreview ? (
144	        <div className="w-full mb-2">
145	          {article}
146	          <MemoCommentListView />
147	        </div>
148	      ) : (
149	        article
150	      )}
151	    </MemoViewContext.Provider>
152	  );
153	};
154	
155	export default memo(MemoView);
```

